Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'REMITEMPERIODO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remItemPeriodo1.FromString(&GridStateDynamicFilter.Value) If not &remItemPeriodo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterremItemPeriodoDescription = format('%1 (%2)', "de Consumo", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterremItemPeriodoDescription = format('%1 (%2)', "de Consumo", "WWP_FilterContains") EndCase &remItemPeriodo = &remItemPeriodo1 print printBlockFilterremItemPeriodo EndIf Case &DynamicFiltersSelector1 = !'REMITEMVALIDADE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remItemValidade1.FromString(&GridStateDynamicFilter.Value) &remItemValidade_To1.FromString(&GridStateDynamicFilter.ValueTo) If not &remItemValidade1.IsEmpty() OR not &remItemValidade_To1.IsEmpty() &FixedValueOperatorDsc = "Validade" Do Case Case &DynamicFiltersOperator1 = 0 &FixedValueOperatorValue = "WWP_FilterPast" print printBlockFixedValueOperator Case &DynamicFiltersOperator1 = 1 &FixedValueOperatorValue = "WWP_FilterToday" print printBlockFixedValueOperator Case &DynamicFiltersOperator1 = 2 &FixedValueOperatorValue = "WWP_FilterInTheFuture" print printBlockFixedValueOperator Case &DynamicFiltersOperator1 = 3 &FilterremItemValidadeDescription = format('%1 (%2)', "Validade", "WWP_FilterRange") &remItemValidade = &remItemValidade1 print printBlockFilterremItemValidade &FilterremItemValidadeDescription = format('%1 (%2) %3', "Validade", "WWP_FilterRange", "") &remItemValidade = &remItemValidade_To1 print printBlockFilterremItemValidade EndCase EndIf Case &DynamicFiltersSelector1 = !'REMTIPOREMESSA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remTipoRemessa1.FromString(&GridStateDynamicFilter.Value) If not &remTipoRemessa1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterremTipoRemessaDescription = format('%1 (%2)', "Tipo Remessa", "=") EndCase &remTipoRemessa = &remTipoRemessa1 print printBlockFilterremTipoRemessa EndIf Case &DynamicFiltersSelector1 = !'REMITEMLOTE' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remItemLote1.FromString(&GridStateDynamicFilter.Value) If not &remItemLote1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterremItemLoteDescription = format('%1 (%2)', "Lote", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterremItemLoteDescription = format('%1 (%2)', "Lote", "WWP_FilterContains") EndCase &remItemLote = &remItemLote1 print printBlockFilterremItemLote EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'REMITEMPERIODO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remItemPeriodo2.FromString(&GridStateDynamicFilter.Value) If not &remItemPeriodo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterremItemPeriodoDescription = format('%1 (%2)', "de Consumo", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterremItemPeriodoDescription = format('%1 (%2)', "de Consumo", "WWP_FilterContains") EndCase &remItemPeriodo = &remItemPeriodo2 print printBlockFilterremItemPeriodo EndIf Case &DynamicFiltersSelector2 = !'REMITEMVALIDADE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remItemValidade2.FromString(&GridStateDynamicFilter.Value) &remItemValidade_To2.FromString(&GridStateDynamicFilter.ValueTo) If not &remItemValidade2.IsEmpty() OR not &remItemValidade_To2.IsEmpty() &FixedValueOperatorDsc = "Validade" Do Case Case &DynamicFiltersOperator2 = 0 &FixedValueOperatorValue = "WWP_FilterPast" print printBlockFixedValueOperator Case &DynamicFiltersOperator2 = 1 &FixedValueOperatorValue = "WWP_FilterToday" print printBlockFixedValueOperator Case &DynamicFiltersOperator2 = 2 &FixedValueOperatorValue = "WWP_FilterInTheFuture" print printBlockFixedValueOperator Case &DynamicFiltersOperator2 = 3 &FilterremItemValidadeDescription = format('%1 (%2)', "Validade", "WWP_FilterRange") &remItemValidade = &remItemValidade2 print printBlockFilterremItemValidade &FilterremItemValidadeDescription = format('%1 (%2) %3', "Validade", "WWP_FilterRange", "") &remItemValidade = &remItemValidade_To2 print printBlockFilterremItemValidade EndCase EndIf Case &DynamicFiltersSelector2 = !'REMTIPOREMESSA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remTipoRemessa2.FromString(&GridStateDynamicFilter.Value) If not &remTipoRemessa2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterremTipoRemessaDescription = format('%1 (%2)', "Tipo Remessa", "=") EndCase &remTipoRemessa = &remTipoRemessa2 print printBlockFilterremTipoRemessa EndIf Case &DynamicFiltersSelector2 = !'REMITEMLOTE' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remItemLote2.FromString(&GridStateDynamicFilter.Value) If not &remItemLote2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterremItemLoteDescription = format('%1 (%2)', "Lote", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterremItemLoteDescription = format('%1 (%2)', "Lote", "WWP_FilterContains") EndCase &remItemLote = &remItemLote2 print printBlockFilterremItemLote EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'REMITEMPERIODO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remItemPeriodo3.FromString(&GridStateDynamicFilter.Value) If not &remItemPeriodo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterremItemPeriodoDescription = format('%1 (%2)', "de Consumo", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterremItemPeriodoDescription = format('%1 (%2)', "de Consumo", "WWP_FilterContains") EndCase &remItemPeriodo = &remItemPeriodo3 print printBlockFilterremItemPeriodo EndIf Case &DynamicFiltersSelector3 = !'REMITEMVALIDADE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remItemValidade3.FromString(&GridStateDynamicFilter.Value) &remItemValidade_To3.FromString(&GridStateDynamicFilter.ValueTo) If not &remItemValidade3.IsEmpty() OR not &remItemValidade_To3.IsEmpty() &FixedValueOperatorDsc = "Validade" Do Case Case &DynamicFiltersOperator3 = 0 &FixedValueOperatorValue = "WWP_FilterPast" print printBlockFixedValueOperator Case &DynamicFiltersOperator3 = 1 &FixedValueOperatorValue = "WWP_FilterToday" print printBlockFixedValueOperator Case &DynamicFiltersOperator3 = 2 &FixedValueOperatorValue = "WWP_FilterInTheFuture" print printBlockFixedValueOperator Case &DynamicFiltersOperator3 = 3 &FilterremItemValidadeDescription = format('%1 (%2)', "Validade", "WWP_FilterRange") &remItemValidade = &remItemValidade3 print printBlockFilterremItemValidade &FilterremItemValidadeDescription = format('%1 (%2) %3', "Validade", "WWP_FilterRange", "") &remItemValidade = &remItemValidade_To3 print printBlockFilterremItemValidade EndCase EndIf Case &DynamicFiltersSelector3 = !'REMTIPOREMESSA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remTipoRemessa3.FromString(&GridStateDynamicFilter.Value) If not &remTipoRemessa3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterremTipoRemessaDescription = format('%1 (%2)', "Tipo Remessa", "=") EndCase &remTipoRemessa = &remTipoRemessa3 print printBlockFilterremTipoRemessa EndIf Case &DynamicFiltersSelector3 = !'REMITEMLOTE' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remItemLote3.FromString(&GridStateDynamicFilter.Value) If not &remItemLote3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterremItemLoteDescription = format('%1 (%2)', "Lote", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterremItemLoteDescription = format('%1 (%2)', "Lote", "WWP_FilterContains") EndCase &remItemLote = &remItemLote3 print printBlockFilterremItemLote EndIf EndCase EndIf EndIf EndIf If not (&TFremItemProduto.IsEmpty() AND &TFremItemProduto_To.IsEmpty()) print printBlockTFremItemProduto &TFremItemProduto_To_Description = format('%1 (%2)', "Codigo", "WWP_TSTo") print printBlockTFremItemProduto_To EndIf If not &TFremItemProdutoDescricao_Sel.IsEmpty() print printBlockTFremItemProdutoDescricao_Sel Else If not &TFremItemProdutoDescricao.IsEmpty() print printBlockTFremItemProdutoDescricao EndIf EndIf If not &TFremItemUnidade_Sel.IsEmpty() print printBlockTFremItemUnidade_Sel Else If not &TFremItemUnidade.IsEmpty() print printBlockTFremItemUnidade EndIf EndIf If not (&TFremItemQtdeEmbalagens.IsEmpty() AND &TFremItemQtdeEmbalagens_To.IsEmpty()) print printBlockTFremItemQtdeEmbalagens &TFremItemQtdeEmbalagens_To_Description = format('%1 (%2)', "Qtde Embalagens", "WWP_TSTo") print printBlockTFremItemQtdeEmbalagens_To EndIf If not &TFremItemPesoUnidade_Sel.IsEmpty() print printBlockTFremItemPesoUnidade_Sel Else If not &TFremItemPesoUnidade.IsEmpty() print printBlockTFremItemPesoUnidade EndIf EndIf If not (&TFremItemPesoConsumo.IsEmpty() AND &TFremItemPesoConsumo_To.IsEmpty()) print printBlockTFremItemPesoConsumo &TFremItemPesoConsumo_To_Description = format('%1 (%2)', "Peso Unitário", "WWP_TSTo") print printBlockTFremItemPesoConsumo_To EndIf If not (&TFremItemPesoTotal.IsEmpty() AND &TFremItemPesoTotal_To.IsEmpty()) print printBlockTFremItemPesoTotal &TFremItemPesoTotal_To_Description = format('%1 (%2)', "Peso Total", "WWP_TSTo") print printBlockTFremItemPesoTotal_To EndIf If not &TFremTipoRemessa_Sel.IsEmpty() print printBlockTFremTipoRemessa_Sel Else If not &TFremTipoRemessa.IsEmpty() print printBlockTFremTipoRemessa EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsremessaitem order remItemPeriodo when &OrderedBy = 1 order prefCodigo remCodigo remItemProduto when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remItemProduto) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo remCodigo remItemProdutoDescricao when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remItemProdutoDescricao) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo remCodigo remItemUnidade when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remItemUnidade) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo remCodigo remItemPesoUnidade when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remItemPesoUnidade) when &OrderedBy = 5 AND &OrderedDsc = True order prefCodigo remCodigo remItemPesoConsumo when &OrderedBy = 6 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remItemPesoConsumo) when &OrderedBy = 6 AND &OrderedDsc = True order prefCodigo remCodigo remItemPesoTotal when &OrderedBy = 7 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remItemPesoTotal) when &OrderedBy = 7 AND &OrderedDsc = True order prefCodigo remCodigo remTipoRemessa when &OrderedBy = 8 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remTipoRemessa) when &OrderedBy = 8 AND &OrderedDsc = True
using trnsremessaitemWWDS(&prefCodigo, &remCodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &remItemPeriodo1, &remItemValidade1 , &remItemValidade_To1, &remTipoRemessa1, &remItemLote1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &remItemPeriodo2, &remItemValidade2, &remItemValidade_To2, &remTipoRemessa2, &remItemLote2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &remItemPeriodo3, &remItemValidade3, &remItemValidade_To3, &remTipoRemessa3 , &remItemLote3, &TFremItemProduto, &TFremItemProduto_To, &TFremItemProdutoDescricao, &TFremItemProdutoDescricao_Sel, &TFremItemUnidade , &TFremItemUnidade_Sel, &TFremItemQtdeEmbalagens, &TFremItemQtdeEmbalagens_To, &TFremItemPesoUnidade, &TFremItemPesoUnidade_Sel, &TFremItemPesoConsumo , &TFremItemPesoConsumo_To, &TFremItemPesoTotal, &TFremItemPesoTotal_To, &TFremTipoRemessa, &TFremTipoRemessa_Sel) Where prefCodigo = &prefCodigo
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsremessaitemWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsremessaitemWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsremessaitemWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFREMITEMPRODUTO" &TFremItemProduto.FromString(&GridStateFilterValue.Value) &TFremItemProduto_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMITEMPRODUTODESCRICAO" &TFremItemProdutoDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMITEMPRODUTODESCRICAO_SEL" &TFremItemProdutoDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMITEMUNIDADE" &TFremItemUnidade.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMITEMUNIDADE_SEL" &TFremItemUnidade_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMITEMQTDEEMBALAGENS" &TFremItemQtdeEmbalagens.FromString(&GridStateFilterValue.Value) &TFremItemQtdeEmbalagens_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMITEMPESOUNIDADE" &TFremItemPesoUnidade.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMITEMPESOUNIDADE_SEL" &TFremItemPesoUnidade_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMITEMPESOCONSUMO" &TFremItemPesoConsumo.FromString(&GridStateFilterValue.Value) &TFremItemPesoConsumo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMITEMPESOTOTAL" &TFremItemPesoTotal.FromString(&GridStateFilterValue.Value) &TFremItemPesoTotal_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMTIPOREMESSA" &TFremTipoRemessa.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMTIPOREMESSA_SEL" &TFremTipoRemessa_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&REMCODIGO" &remCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
